with m1: st.markdown(f'<div class="metric-card"><div class="metric-lbl">Total MW ({modo.split()[0]})</div><div class="metric-val">{total_mw:,}</div></div>', unsafe_allow_html=True)
with m2: st.markdown(f'<div class="metric-card"><div class="metric-lbl">Nodo top ranked</div><div class="metric-val" style="font-size:1.1rem">{top_nodo["nombre"] if top_nodo is not None else "-"}</div></div>', unsafe_allow_html=True)
with m3: st.markdown(f'<div class="metric-card"><div class="metric-lbl">Viento promedio</div><div class="metric-val">{v_prom:.1f} <span style="font-size:1rem">m/s</span></div></div>', unsafe_allow_html=True)
with m4: st.markdown(f'<div class="metric-card"><div class="metric-lbl">Desarrollar (AURA)</div><div class="metric-val">{n_aura}</div></div>', unsafe_allow_html=True)
st.markdown("---")

tab1,tab2,tab3,tab4 = st.tabs(["🗺️ Mapa", "🏆 Ranking", "📊 Por corredor", "📋 Tabla completa"])

with tab1:
    dm = df_f.dropna(subset=["lat","lon"]).copy()
    st.markdown(f"### Mapa de oportunidades ({len(dm)} nodos con coordenadas)")
    st.caption(f"Tamano = MW - Color = velocidad de viento (m/s)")
    if dm.empty: st.info("Sin nodos con coordenadas.")
    else:
        fig = px.scatter_mapbox(dm, lat="lat", lon="lon", color="viento", size="cap", size_max=28,
            color_continuous_scale="Turbo", hover_name="nombre",
            hover_data={"id":True,"corredor":True,"viento":True,"cap":True,"rk":True,"v_fuente":True,"lat":False,"lon":False},
            zoom=3.7, center={"lat":-38,"lon":-64}, mapbox_style="open-street-map", labels={"viento":"m/s","cap":"MW"})
        fig.update_layout(height=560, margin={"r":0,"t":0,"l":0,"b":0})
        st.plotly_chart(fig, use_container_width=True)

with tab2:
    ci,cd = st.columns(2)
    with ci:
        st.markdown("### ⭐ Para desarrollar (AURA)")
        da = df_f[df_f.segmento=="⭐ Desarrollar (AURA)"].sort_values("rk").head(25)
        if da.empty: st.info("Sin nodos.")
        for _,r in da.iterrows():
            cc=COLOR_MAP.get(r.corredor,"#888")
            fb = "📡" if r.v_fuente=="real" else "📍"
            st.markdown(f'<div style="border-left:3px solid {cc};padding:6px 10px;margin:4px 0;background:#FAFAFA;border-radius:0 6px 6px 0"><span style="font-weight:600;color:#0F6E56">#{int(r["rk"])} {r["nombre"]}</span> <span style="font-size:.8rem;color:#666">{r.corredor}</span><br><span style="font-size:.85rem">{fb} <b>{r.viento} m/s</b> - <b>{int(r.cap)} MW</b> - score {r.score:.3f}</span></div>', unsafe_allow_html=True)
    with cd:
        st.markdown("### 🤝 Para ofrecer a terceros")
        dt = df_f[df_f.segmento=="🤝 Ofrecer a terceros"].sort_values("rk").head(25)
        if dt.empty: st.info("Sin nodos.")
        for _,r in dt.iterrows():
            cc=COLOR_MAP.get(r.corredor,"#888")
            fb = "📡" if r.v_fuente=="real" else "📍"
            st.markdown(f'<div style="border-left:3px solid {cc};padding:6px 10px;margin:4px 0;background:#F0FAF5;border-radius:0 6px 6px 0"><span style="font-weight:600;color:#14A085">#{int(r["rk"])} {r["nombre"]}</span> <span style="font-size:.8rem;color:#666">{r.corredor}</span><br><span style="font-size:.85rem">{fb} <b>{r.viento} m/s</b> - <b>{int(r.cap)} MW</b> - score {r.score:.3f}</span></div>', unsafe_allow_html=True)
    st.caption("📡 = viento medido (Global Wind Atlas) - 📍 = viento estimado por zona")

with tab3:
    st.markdown("### Capacidad y viento por corredor")
    if not df_f.empty:
        res = df_f.groupby("corredor").agg(nodos=("id","count"), mw_total=("cap","sum"),
            viento_prom=("viento","mean")).reset_index().sort_values("mw_total", ascending=False)
        g1,g2 = st.columns(2)
        with g1:
            f1 = px.bar(res.sort_values("mw_total"), x="mw_total", y="corredor", orientation="h",
                color="corredor", color_discrete_map=COLOR_MAP, text="mw_total", labels={"mw_total":"MW","corredor":""})
            f1.update_traces(texttemplate="%{text} MW", textposition="outside")
            f1.update_layout(height=400, showlegend=False, plot_bgcolor="white", paper_bgcolor="white", title="MW por corredor")
            st.plotly_chart(f1, use_container_width=True)
        with g2:
            f2 = px.bar(res.sort_values("viento_prom"), x="viento_prom", y="corredor", orientation="h",
                color="viento_prom", color_continuous_scale="Turbo", text=res.sort_values("viento_prom")["viento_prom"].round(1),
                labels={"viento_prom":"Viento medio (m/s)","corredor":""})
            f2.update_traces(texttemplate="%{text} m/s", textposition="outside")
            f2.update_layout(height=400, showlegend=False, plot_bgcolor="white", paper_bgcolor="white",
                title="Viento promedio por corredor", coloraxis_showscale=False)
            st.plotly_chart(f2, use_container_width=True)
        rs = res.copy(); rs.columns=["Corredor","Nodos","MW totales","Viento medio"]
        st.dataframe(rs, use_container_width=True, hide_index=True, column_config={
            "MW totales": st.column_config.NumberColumn(format="%d MW"),
            "Viento medio": st.column_config.NumberColumn(format="%.1f m/s")})

with tab4:
    st.markdown("### Tabla completa")
    cols=["rk","nombre","corredor","viento","v_fuente","cap","cap_refa","cap_pleno","score","segmento","id"]
    ds=df_f[cols].sort_values("rk").copy()
    ds.columns=["Rk","Nombre","Corredor","Viento","Fuente","Cap. activa","Ref A","Pleno","Score","Segmento","ID"]
    st.dataframe(ds, use_container_width=True, height=500, hide_index=True, column_config={
        "Rk": st.column_config.NumberColumn(format="%d"),
        "Viento": st.column_config.NumberColumn(format="%.2f m/s"),
        "Cap. activa": st.column_config.NumberColumn(format="%d MW"),
        "Ref A": st.column_config.NumberColumn(format="%d"),
        "Pleno": st.column_config.NumberColumn(format="%d"),
        "Score": st.column_config.NumberColumn(format="%.3f")})
    st.caption("Fuente 'real' = Global Wind Atlas (medido). 'estimado' = promedio por zona (refinar con coordenadas).")

